def transform(grid):
    starts = [0, 5, 10, 15]
    # Color precedence observed in demo: 9 > 4 > 8 > 5 (zero is transparent).
    rank = {0: 0, 5: 1, 8: 2, 4: 3, 9: 4}
    out = [[0] * 4 for _ in range(4)]
    for r in range(4):
        for c in range(4):
            vals = [grid[r][s+c] for s in starts]
            out[r][c] = max(vals, key=lambda v: rank.get(v, v))
    return out
